From 44104736e491d764a20897cf23e8e29025659502 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 17:45:19 +0100
Subject: [PATCH] applets/kickoff: switch tabs with horizontal scrolling

Scrolling sideways over Kickoff's content did nothing, even though the
tabs slide horizontally. Now a two-finger horizontal swipe on a touchpad
or a horizontal mouse wheel switches between the two tabs.

BUG: 504886
---
 applets/kickoff/NormalPage.qml | 35 ++++++++++++++++++++++++++++++++++
 1 file changed, 35 insertions(+)

diff --git a/applets/kickoff/NormalPage.qml b/applets/kickoff/NormalPage.qml
index 6a2161d5f2..facf6772ae 100644
--- a/applets/kickoff/NormalPage.qml
+++ b/applets/kickoff/NormalPage.qml
@@ -37,6 +37,41 @@ EmptyPage {
                 }
             }
         }
+        // Above the pages so horizontal scrolling reaches it before the views,
+        // non-blocking so they still get vertical scrolling.
+        Item {
+            anchors.fill: parent
+            z: 1
+            WheelHandler {
+                id: tabSwipeHandler
+                acceptedDevices: PointerDevice.Mouse | PointerDevice.TouchPad
+                orientation: Qt.Horizontal
+                blocking: false
+                onActiveChanged: {
+                    if (!tabSwipeHandler.active) {
+                        tabSwipeHandler.rotation = 0
+                    }
+                }
+                onWheel: event => {
+                    if (Math.abs(event.angleDelta.x) <= Math.abs(event.angleDelta.y)) {
+                        tabSwipeHandler.rotation = 0
+                        return
+                    }
+                    const tabBar = footer.tabBar
+                    const forward = stackView.mirrored ? tabSwipeHandler.rotation >= 15 : tabSwipeHandler.rotation <= -15
+                    const backward = stackView.mirrored ? tabSwipeHandler.rotation <= -15 : tabSwipeHandler.rotation >= 15
+                    if (forward && tabBar.currentIndex < tabBar.count - 1) {
+                        tabBar.incrementCurrentIndex()
+                        tabSwipeHandler.rotation = 0
+                    } else if (backward && tabBar.currentIndex > 0) {
+                        tabBar.decrementCurrentIndex()
+                        tabSwipeHandler.rotation = 0
+                    } else if (forward || backward) {
+                        tabSwipeHandler.rotation = 0
+                    }
+                }
+            }
+        }
     }

     footer: Footer {
